-- Generated by scripts/generate_demo_cvs.py; safe to reapply to an existing demo database.
CREATE TABLE IF NOT EXISTS candidates (
 candidate_number VARCHAR(50) PRIMARY KEY, name VARCHAR(100) NOT NULL,
 surname VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE,
 cv_document BYTEA, cv_filename VARCHAR(255), cv_content_type VARCHAR(100),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS candidates_updated_idx ON candidates(updated_at,candidate_number COLLATE "C");
